const keyL = new THREE.DirectionalLight(0xffffff, 0.85); keyL.position.set(-8, 10, 8); scene.add(keyL);
const fillL = new THREE.DirectionalLight(0xffffff, 0.40); fillL.position.set(10, 3, 7); scene.add(fillL);
