tubeBody.position.y = 1.15; tubeBody.renderOrder = 10; coilGroup.add(tubeBody);
const tubeBot = new THREE.Mesh(new THREE.SphereGeometry(0.32, 24, 12, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), glassMat);
tubeBot.position.y = -3.2; tubeBot.renderOrder = 10; coilGroup.add(tubeBot);
const tubeLip = new THREE.Mesh(new THREE.TorusGeometry(0.33, 0.045, 8, 28),
  new THREE.MeshStandardMaterial({ color: 0xbfe0ee, roughness: 0.15, metalness: 0.1, transparent: true, opacity: 0.8 }));
tubeLip.rotation.x = Math.PI / 2; tubeLip.position.y = 5.48; tubeLip.renderOrder = 11; coilGroup.add(tubeLip);

