const sample = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.26, 5.55, 24), sampleMat);
sample.position.y = -0.375; sample.userData.noHighlight = true; coilGroup.add(sample);
const sampleCap = new THREE.Mesh(new THREE.SphereGeometry(0.26, 20, 10, 0, Math.PI * 2, Math.PI / 2, Math.PI / 2), sampleMat);
sampleCap.position.y = -3.15; sampleCap.userData.noHighlight = true; coilGroup.add(sampleCap);
