    new THREE.MeshStandardMaterial({ color: 0x155f96, roughness: 0.4 }));
  r1.position.y = y + (y > 0 ? 0.28 : -0.28); coilGroup.add(hlMat(r1));
});

/* ── magnet poles ─────────────────────────────────────────────────────────── */
const magGroup = new THREE.Group(); scene.add(magGroup);
const steelMat = new THREE.MeshStandardMaterial({ color: 0xb9bcc0, roughness: 0.3, metalness: 0.7 });
const faceMat = new THREE.MeshStandardMaterial({ color: 0xd4d7da, roughness: 0.45, metalness: 0.5 });
function makeLetterTex(ch) {
  const cv = document.createElement('canvas'); cv.width = cv.height = 128;
  const x = cv.getContext('2d');
  x.clearRect(0, 0, 128, 128);
  x.fillStyle = '#ffffff'; x.font = 'bold 100px Helvetica,Arial,sans-serif';
  x.textAlign = 'center'; x.textBaseline = 'middle'; x.fillText(ch, 64, 68);
  const t = new THREE.CanvasTexture(cv); t.anisotropy = 4; return t;
}
function makePole(cx, letter) {
  const g = new THREE.Group(); g.position.set(cx, 0.2, 0); magGroup.add(g);
