];
function bToFrac(B) { return 0.9615 * B - 1.3961; }
function drawScreen(B0, pulse) {
  const g = scrCtx;
  g.fillStyle = '#a9d8ec'; g.fillRect(0, 0, SCW, SCH);
  g.fillStyle = '#b8e0f0'; g.fillRect(0, 0, SCW, 26);
  const baseY = SCH * 0.70, x0 = 26, x1 = SCW - 26;
  // sweep cursor
  const cf = Math.max(0, Math.min(1, bToFrac(B0)));
  g.strokeStyle = 'rgba(60,90,110,0.45)'; g.lineWidth = 1.5;
  g.setLineDash([6, 6]); g.beginPath();
  g.moveTo(x0 + cf * (x1 - x0), 34); g.lineTo(x0 + cf * (x1 - x0), baseY); g.stroke();
  g.setLineDash([]);
  // peaks
  PEAKS.forEach((p) => {
    const near = Math.abs(B0 - p.B) < 0.03;
    if (B0 < p.B - 0.03) return;
    const boost = near ? 1 + 0.14 * (0.5 + 0.5 * Math.sin(pulse * 8)) : 1;
    const px = x0 + p.f * (x1 - x0);
    const ph = p.h * SCH * 0.62 * boost;
    g.strokeStyle = near ? '#ff4a22' : '#8f1810';
    g.lineWidth = near ? 5 : 2.6;
    g.beginPath(); g.moveTo(px, baseY); g.lineTo(px, baseY - ph); g.stroke();
  });
  // baseline
  g.strokeStyle = '#d12a1f'; g.lineWidth = 3.4;
  g.beginPath(); g.moveTo(x0, baseY); g.lineTo(x1, baseY); g.stroke();
  // readout
  g.fillStyle = '#14384c'; g.font = '20px Helvetica,Arial,sans-serif';
  g.fillText('\u03BD = 9.56    B\u2080 = ' + B0.toFixed(2) + ' T', 30, SCH - 24);
  scrTex.needsUpdate = true;
}

