/* ── controls logic ───────────────────────────────────────────────────────── */
const slider = document.getElementById('fieldStrength');
const fieldVal = document.getElementById('fieldVal');
const resStatus = document.getElementById('resStatus');
let B0 = parseFloat(slider.value);
let resStrength = 0;

function applyField(v, pulse) {
  B0 = v;
  fieldVal.textContent = v.toFixed(2) + ' T';
  let best = null, bd = 1e9;
  PEAKS.forEach((p, i) => { const dd = Math.abs(v - p.B); if (dd < bd) { bd = dd; best = i; } });
  resStrength = Math.max(0, 1 - bd / 0.03);
  const em = resStrength;
  sampleMat.emissive.setRGB(1.0 * em, 0.88 * em, 0.62 * em);
  sampleMat.emissiveIntensity = em * 1.4;
  glow.material.opacity = em * 0.20;
  if (resStrength > 0.02) {
    resStatus.innerHTML = '<b style="color:#c23">Resonance!</b> at B\u2080 \u2248 ' + PEAKS[best].B.toFixed(2) +
      ' T \u2014 one set of nuclei absorbs; its peak brightens on the monitor.';
  } else {
    const nxt = PEAKS.find((p) => p.B > v);
    resStatus.innerHTML = 'No absorption at this field. ' +
      (nxt ? 'Next resonance at B\u2080 = ' + nxt.B.toFixed(2) + ' T.' : 'All four resonances have been swept.');
  }
  drawScreen(v, pulse === undefined ? 0 : pulse);
}
