/* ── own update loop ──────────────────────────────────────────────────────── */
const _tmpV = new THREE.Vector3();
function tick() {
  requestAnimationFrame(tick);
  const t = performance.now() / 1000;
  if (tween) {
    const k = Math.min(1, (performance.now() - tween.t0) / tween.dur);
    const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
    const v = tween.from + (tween.to - tween.from) * e;
    slider.value = v.toFixed(2);
    applyField(v, t);
    if (k >= 1) tween = null;
  } else if (resStrength > 0.02) {
    drawScreen(B0, t);
    sampleMat.emissiveIntensity = resStrength * (1.1 + 0.5 * Math.sin(t * 8));
    glow.material.opacity = resStrength * (0.16 + 0.07 * Math.sin(t * 8));
  }
  // component highlight
  COMPS.forEach((c, i) => {
    const target = (i === activeComp) ? 0.30 + 0.22 * (0.5 + 0.5 * Math.sin(t * 5)) : 0;
    c.meshes.forEach((m) => { m.material.emissiveIntensity = target; });
  });
  // cable pulses
  SEGS.forEach((s) => {
    const em = s.active ? 0.45 + 0.25 * Math.sin(t * 6) : 0;
    s.meshes.forEach((m) => { m.material.emissiveIntensity = em; });
    if (s.active) {
      s.t = (s.t + 0.012) % 1;
      s.curve.getPoint(s.t, _tmpV);
      s.pulse.position.copy(_tmpV);
      s.pulse.material.color.setHSL(0.14, 1.0, 0.75);
    }
  });
}
